    if (msg.hasMemory()) {
      result.putAll(adminMemoryMetricsToEnvVar(msg.getMemory()));
    }
    if (msg.hasCpu()) {
      result.putAll(adminCpuMetricsToEnvVar(msg.getCpu()));
    }
    if (msg.hasDisk()) {
      result.putAll(adminDiskMetricsToEnvVar(msg.getDisk()));
    }
    result.put("PROTO_ADMIN_NODE_METRICS_TIMESTAMP_MS", String.valueOf(msg.getTimestampMs()));
